> crayon:::win10_build
function ()
{
    os <- utils::sessionInfo()$running
    if (!grepl("^Windows 10 ", os))
        return(0L)
    mch <- re_match(os, "[(]build (?<build>[0-9]+)[)]")
    mch <- suppressWarnings(as.integer(mch))
    if (is.na(mch))
        return(0L)
    mch
}
